import formatNumber from 'Common/Functions/FormatNumber';

/**
 * Formats the red warning banner for the Remediation widget.
 * Example: "12 high-risk still open — 5 critical | 4 high awaiting triage."
 *
 * translations must include: highRisk, stillOpen, critical, highAwaitingTriage
 */
export function formatRemediationWarning ({ openTotal, critical, high, translations }) {
  const parts = [];
  if (critical > 0) parts.push(`${formatNumber(critical)} ${translations.critical}`);
  if (high > 0) parts.push(`${formatNumber(high)} ${translations.highAwaitingTriage}`);
  const breakdown = parts.join(' | ');
  const base = `${formatNumber(openTotal)} ${translations.highRisk} ${translations.stillOpen}`;
  return breakdown ? `${base} — ${breakdown}.` : `${base}.`;
}

/**
 * Formats the summary footer for the BySeverity widget.
 * Returns two strings for left and right sides.
 * Example left: "8 high-risk | 4 medium-low"  right: "+1 unclassified"
 *
 * translations must include: highRisk, mediumLow, unclassified
 */
export function formatSeverityFooter ({ critical, high, med, low, unclassified, translations }) {
  const highRisk = critical + high;
  const mediumLow = med + low;

  const leftParts = [];
  if (highRisk > 0) leftParts.push(`${formatNumber(highRisk)} ${translations.highRisk}`);
  if (mediumLow > 0) leftParts.push(`${formatNumber(mediumLow)} ${translations.mediumLow}`);

  return {
    leftText: leftParts.join(' | '),
    rightText: unclassified > 0 ? `+${formatNumber(unclassified)} ${translations.unclassified}` : ''
  };
}
